-- Besoins du 11/10 (point 8) : libelles de menus courts (25 caracteres au plus).
-- Le libelle affiche est str_DESCRIPTION ; le texte long est garde dans str_VALUE (infobulle) quand il est plus
-- complet que l'infobulle actuelle. Un menu deja renomme a la main (25 caracteres au plus) n'est pas touche.

UPDATE t_sous_menu SET str_VALUE = IF(CHAR_LENGTH(IFNULL(str_VALUE, '')) >= CHAR_LENGTH(str_DESCRIPTION), str_VALUE, str_DESCRIPTION), str_DESCRIPTION = 'Étiquettage Pro' WHERE str_COMPOSANT = 'etiquetagepro' AND CHAR_LENGTH(str_DESCRIPTION) > 25;
